import sys

class Iter:
    def __init__(self, arr):
        self.arr = arr
        self.i = 0
    def has_next(self):
        return self.i < len(self.arr)
    def next(self):
        v = self.arr[self.i]
        self.i += 1
        return v

class PeekingIterator:
    def __init__(self, it):
        self.it = it
        self.has_cache = False
        self.cache = 0
    def peek(self):
        if not self.has_cache:
            self.cache = self.it.next()
            self.has_cache = True
        return self.cache
    def next(self):
        if self.has_cache:
            self.has_cache = False
            return self.cache
        return self.it.next()
    def has_next(self):
        return self.has_cache or self.it.has_next()

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    arr = list(map(int, data[1:1 + m]))
    q = int(data[1 + m])
    ops = data[2 + m:2 + m + q]
    p = PeekingIterator(Iter(arr))
    out = []
    for op in ops:
        if op == 'next':
            out.append(str(p.next()))
        elif op == 'peek':
            out.append(str(p.peek()))
        else:
            out.append('true' if p.has_next() else 'false')
    print('\n'.join(out))

main()

